print(book.read_time())

class Temperature:
    def __init__(self, celsius=0):
        self.celsius = celsius

    @property
    def celsius(self):
        return self._celsius

    @celsius.setter
    def celsius(self, value):
        if value < -273.15:
            raise ValueError("INVALID")
        self._celsius = value

    @property
    def fahrenheit(self):
        return self._celsius * 9 / 5 + 32

try:
    c = float(input())
    t = Temperature(c)
    print(f"{t.fahrenheit:.1f}F")
except ValueError:
    print("INVALID")

