import time

def timer(func):
    def wrapper(*args, **kwargs):
        start = time.perf_counter()
        result = func(*args, **kwargs)
        end = time.perf_counter()
        elapsed = (end - start) * 1000
        print(f"结果:{result} 耗时:{elapsed:.1f}ms")
        return result
    return wrapper

@timer
def slow_add(n):
    total = 0
    for i in range(1, n + 1):
        total += i
    return total

n = int(input())
slow_add(n)

